#!/usr/bin/env node
/**
 * scripts/fix-website-visibility.mjs
 *
 * Patches all existing saved websites in the DB for two known issues:
 *
 * Issue 1 — Invisible content (scroll-reveal bug)
 *   IntersectionObserver scroll-reveal patterns generated by older prompts
 *   leave all elements at opacity:0 inside iframes. Fix: inject a CSS override
 *   + IO shim that force-reveals everything immediately.
 *
 * Issue 2 — Empty body (max_tokens truncation bug)
 *   Older generations hit max_tokens before writing <body> content, leaving
 *   a site with only <head> meta tags and a blank/invisible page. Fix: inject
 *   a visible "Regenerate required" message into the body so users know what
 *   happened instead of seeing a blank page.
 *
 * Both fixes are idempotent — already-patched sites are skipped.
 * Safe to run multiple times.
 *
 * Run once after deploying (auto-runs on Render via buildCommand):
 *   node scripts/fix-website-visibility.mjs
 */

import { PrismaClient } from '@prisma/client'

const prisma = new PrismaClient()

// ── Fix 1: Visibility override (scroll-reveal bug) ───────────────────────────
const VISIBILITY_STYLE = `
<style id="bs-visibility-fix">
/* BrandSyndicate legacy fix: force scroll-reveal hidden elements visible */
[class*="reveal"],[class*="hidden"],[class*="fade-in"],[class*="fadeIn"],
[class*="slide-in"],[class*="slideIn"],[class*="animate"],[class*="in-view"],
[class*="is-visible"],[data-reveal],[data-animate],[data-aos] {
  opacity: 1 !important;
  transform: none !important;
  visibility: visible !important;
  transition: none !important;
}
</style>
<script>
(function(){
  try {
    var _NIO = window.IntersectionObserver;
    window.IntersectionObserver = function(cb, opts) {
      var io = new _NIO(cb, opts);
      var _obs = io.observe.bind(io);
      io.observe = function(el) {
        if (el && el.style) {
          el.style.opacity = '';
          el.style.transform = '';
          el.style.visibility = '';
        }
        if (el && el.classList) {
          ['visible','in-view','is-visible','revealed'].forEach(function(c){ el.classList.add(c); });
        }
        return _obs(el);
      };
      return io;
    };
    window.IntersectionObserver.prototype = _NIO.prototype;
  } catch(e) {}
})();
</script>`

// ── Fix 2: Empty-body patch (max_tokens truncation bug) ──────────────────────
// Injected into the <body> of sites that have meta tags but no visible content.
// The route.ts serves a proper TRUNCATED_HTML page at runtime, but this patch
// makes the stored HTML self-describing if someone downloads it.
const TRUNCATED_BODY_PATCH = `
<!-- bs-truncation-fix: content was cut short during generation -->
<div id="bs-truncation-notice" style="
  display:flex;align-items:center;justify-content:center;
  min-height:100vh;font-family:'DM Mono','Courier New',monospace;
  background:#09090a;color:rgba(255,255,255,0.4);
  flex-direction:column;gap:20px;padding:40px;text-align:center;
">
  <div style="font-size:36px;opacity:0.3">⟳</div>
  <div style="font-size:13px;letter-spacing:0.06em;color:rgba(255,255,255,0.6)">Website Content Incomplete</div>
  <div style="font-size:11px;letter-spacing:0.05em;line-height:1.8;max-width:360px">
    This website's content was cut short during generation.<br>
    Open it in your dashboard and click <strong style="color:#C9A84C">Regenerate</strong> to rebuild it.
  </div>
</div>`

// ── Heuristics ───────────────────────────────────────────────────────────────

function hasVisibilityBug(html) {
  if (!html) return false
  const hasObserver   = /new\s+IntersectionObserver/i.test(html)
  const hasRevealClass = /\.(reveal|in-view|is-visible|fade-in|slideIn|animate)\s*\{[^}]*opacity\s*:\s*0/i.test(html)
  const hasHiddenBase  = /\[data-reveal\]\s*\{[^}]*opacity\s*:\s*0/i.test(html)
  return hasObserver || hasRevealClass || hasHiddenBase
}

function hasEmptyBody(html) {
  if (!html) return true
  const bodyMatch = html.match(/<body[^>]*>([\s\S]*?)<\/body>/i)
  if (!bodyMatch) return true
  const bodyText = bodyMatch[1]
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .trim()
  return bodyText.length < 100
}

// ── Patchers ─────────────────────────────────────────────────────────────────

function patchVisibility(html) {
  if (!html) return html
  if (html.includes('id="bs-visibility-fix"')) return html  // already patched
  if (html.includes('</head>')) {
    return html.replace('</head>', VISIBILITY_STYLE + '\n</head>')
  }
  return VISIBILITY_STYLE + '\n' + html
}

function patchEmptyBody(html) {
  if (!html) return html
  if (html.includes('id="bs-truncation-fix"') || html.includes('id="bs-truncation-notice"')) return html  // already patched

  if (html.includes('<body>') || html.match(/<body[^>]*>/i)) {
    // Insert patch content right after the opening <body> tag
    return html.replace(/(<body[^>]*>)/i, `$1${TRUNCATED_BODY_PATCH}`)
  }
  // No body tag at all — append before </html> or at end
  if (html.includes('</html>')) {
    return html.replace('</html>', `<body>${TRUNCATED_BODY_PATCH}</body>\n</html>`)
  }
  return html + `\n<body>${TRUNCATED_BODY_PATCH}</body>\n</html>`
}

// ── Main ─────────────────────────────────────────────────────────────────────

async function main() {
  console.log('🔍 BrandSyndicate: Website Visibility + Truncation Migration\n')

  const BATCH = 50
  let skip = 0
  let totalChecked      = 0
  let patchedVisibility = 0
  let patchedTruncation = 0
  let totalSkipped      = 0
  let totalErrors       = 0

  while (true) {
    const sites = await prisma.userWebsite.findMany({
      where:   { htmlContent: { not: null } },
      select:  { id: true, slug: true, name: true, htmlContent: true },
      skip,
      take:    BATCH,
      orderBy: { createdAt: 'asc' },
    })

    if (sites.length === 0) break
    skip += BATCH

    for (const site of sites) {
      totalChecked++
      const label = `[${site.slug ?? site.id}] "${site.name ?? 'Untitled'}"`

      try {
        let html    = site.htmlContent ?? ''
        let changed = false

        // ── Fix 2 first: empty body takes priority ──────────────────────────
        if (hasEmptyBody(html) && !html.includes('id="bs-truncation-notice"')) {
          html    = patchEmptyBody(html)
          changed = true
          patchedTruncation++
          process.stdout.write(`  ⚠  ${label} — TRUNCATION PATCHED (empty body)\n`)
        }

        // ── Fix 1: scroll-reveal visibility bug ─────────────────────────────
        if (!html.includes('id="bs-visibility-fix"') && hasVisibilityBug(html)) {
          html    = patchVisibility(html)
          changed = true
          patchedVisibility++
          process.stdout.write(`  ✦  ${label} — VISIBILITY PATCHED\n`)
        }

        if (!changed) {
          totalSkipped++
          process.stdout.write(`  ✓  ${label} — ok, skipping\n`)
          continue
        }

        await prisma.userWebsite.update({
          where: { id: site.id },
          data:  { htmlContent: html },
        })

      } catch (err) {
        totalErrors++
        console.error(`  ✗  ${label} — ERROR:`, err.message)
      }
    }
  }

  console.log('\n────────────────────────────────────────')
  console.log(`Total checked        : ${totalChecked}`)
  console.log(`Visibility patched   : ${patchedVisibility}`)
  console.log(`Truncation patched   : ${patchedTruncation}`)
  console.log(`Skipped (already ok) : ${totalSkipped}`)
  console.log(`Errors               : ${totalErrors}`)
  console.log('────────────────────────────────────────')

  const totalPatched = patchedVisibility + patchedTruncation
  if (totalPatched > 0) {
    console.log(`\n✅ Done. ${totalPatched} site(s) patched.`)
    if (patchedTruncation > 0) {
      console.log(`   ${patchedTruncation} site(s) had empty bodies — users will see a regenerate prompt.`)
    }
  } else {
    console.log('\n✅ Done. No sites needed patching.')
  }
}

main()
  .catch(e => { console.error('Fatal error:', e); process.exit(1) })
  .finally(() => prisma.$disconnect())
